#!/usr/bin/env Rscript
args<-commandArgs(trailingOnly=TRUE);if(length(args)!=2L)stop("Usage: Rscript scripts/local/ytab_validate_one_sample_app_create_hit_file.R <project.yaml> <sample>",call.=FALSE)
all<-commandArgs(trailingOnly=FALSE);self<-normalizePath(sub("^--file=","",grep("^--file=",all,value=TRUE)[[1]]),winslash="/");root<-normalizePath(file.path(dirname(self),"../.."),winslash="/");config<-normalizePath(args[[1]],winslash="/");sample<-args[[2]];project_root<-dirname(dirname(config));hits<-file.path(project_root,"create_hit_file",sample,paste0(sample,"_hits.txt"));manifest<-file.path(project_root,"manifests","create_hit_file",paste0(sample,".create_hit_file_manifest.json"));if(file.exists(hits))stop("Selected sample already has a hit file; refusing to use --force.",call.=FALSE)
app_env<-new.env(parent=.GlobalEnv);source(file.path(root,"app/shiny/app.R"),local=app_env);observed<-new.env(parent=emptyenv());observed$current<-FALSE;observed$running<-FALSE
shiny::testServer(app_env$server,{session$setInputs(project_selector=config,open_project=1);session$flushReact();do.call(session$setInputs,setNames(list(sample),"preprocessing_samples-samples"));session$setInputs(preprocessing_threads=2,create_hit_file_dry_run=FALSE,create_hit_file_force=FALSE,create_hit_file_keep_going=FALSE);session$flushReact();stopifnot(identical(preprocessing_selected_samples(),sample));before<-sample_pipeline_status();row<-before[before$sample==sample,,drop=FALSE];stopifnot(row$mapping=="success",row$hit_file=="ready");session$setInputs(run_create_hit_file=1);session$flushReact();stopifnot(jobs$job_is_running());deadline<-Sys.time()+300;while(jobs$job_is_running()&&Sys.time()<deadline){jobs$poll_job();p<-jobs$current_progress();if(!is.null(p)){observed$running<-observed$running||p$status%in%c("queued","starting","running");observed$current<-observed$current||identical(p$current_item,sample)};Sys.sleep(.1)};jobs$poll_job();p<-jobs$current_progress();stopifnot(!jobs$job_is_running(),observed$running,observed$current,p$status=="success",p$successful_items==1,p$failed_items==0,p$remaining_items==0,identical(preprocessing_selected_samples(),sample),state$values$view=="workspace");after<-app_env$build_sample_pipeline_status(active());row<-after[after$sample==sample,,drop=FALSE];stopifnot(row$hit_file=="success",row$summary=="ready");cat(sprintf("Elapsed seconds: %.3f\nProgress file: %s\n",p$job_elapsed_seconds,jobs$current_job()$progress_file))})
stopifnot(file.exists(hits),file.exists(manifest));cat("Hit file:",hits,"\nManifest:",manifest,"\nPASS\n")
